import { type GuideRunner, GuideService } from "../pr/guide-service.ts";
import { GuideStore } from "../store/guide-store.ts";

const failing: GuideRunner = async () => {
  throw new Error("no guide runner in this test");
};

/** PR guides stored under `dataDir`, generated by `run` (by default, every job fails). */
export function testGuides(dataDir: string, run: GuideRunner = failing): GuideService {
  return new GuideService(new GuideStore(dataDir), run);
}
